CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role text NOT NULL CHECK(role IN ('admin','researcher')), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE UNIQUE INDEX agri_official_identity ON public.agri_reports(state,district,market,commodity,variety,date,source_name) WHERE official;
CREATE TABLE public.agri_sync_state(source text PRIMARY KEY, next_offset integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'not_started', last_success timestamptz, message text, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.agri_sync_state TO anon,authenticated; GRANT ALL ON public.agri_sync_state TO service_role;
ALTER TABLE public.agri_sync_state ENABLE ROW LEVEL SECURITY;
CREATE POLICY sync_public_status ON public.agri_sync_state FOR SELECT TO anon,authenticated USING(true);
CREATE INDEX agri_report_market_series ON public.agri_reports(commodity,state,district,market,variety,source_name,date DESC);
CREATE FUNCTION public.publish_agmarknet_batch(records jsonb, expected_offset integer, next_offset integer, finished boolean) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE current_offset integer; count_rows integer; BEGIN INSERT INTO agri_sync_state(source) VALUES('agmarknet') ON CONFLICT DO NOTHING; SELECT s.next_offset INTO current_offset FROM agri_sync_state s WHERE source='agmarknet' FOR UPDATE; IF current_offset<>expected_offset THEN RAISE EXCEPTION 'Sync cursor changed; retry with current cursor'; END IF; INSERT INTO agri_reports(official,state,district,market,commodity,variety,date,min_price,max_price,modal_price,price_unit,arrivals,arrival_unit,source_name,source_url,retrieved_at,suspicious) SELECT true,r.state,r.district,r.market,r.commodity,r.variety,r.date,r.min_price,r.max_price,r.modal_price,r.price_unit,r.arrivals,r.arrival_unit,'AGMARKNET','https://agmarknet.gov.in',r.retrieved_at,r.suspicious FROM jsonb_to_recordset(records) AS r(state text,district text,market text,commodity text,variety text,date date,min_price numeric,max_price numeric,modal_price numeric,price_unit text,arrivals numeric,arrival_unit text,retrieved_at timestamptz,suspicious boolean) ON CONFLICT(state,district,market,commodity,variety,date,source_name) WHERE official DO UPDATE SET min_price=excluded.min_price,max_price=excluded.max_price,modal_price=excluded.modal_price,arrivals=excluded.arrivals,arrival_unit=excluded.arrival_unit,retrieved_at=excluded.retrieved_at,suspicious=excluded.suspicious; GET DIAGNOSTICS count_rows=ROW_COUNT; UPDATE agri_sync_state SET next_offset=CASE WHEN finished THEN 0 ELSE publish_agmarknet_batch.next_offset END,status=CASE WHEN finished THEN 'snapshot_complete' ELSE 'partial' END,last_success=now(),updated_at=now(),message=count_rows||' source-verified reports published in last batch' WHERE source='agmarknet'; RETURN count_rows; END $$;
REVOKE ALL ON FUNCTION public.publish_agmarknet_batch(jsonb,integer,integer,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.publish_agmarknet_batch(jsonb,integer,integer,boolean) TO service_role;